package com.collabspace.controller; import com.collabspace.dto.AuthDtos.UserResponse;import com.collabspace.dto.UserDtos.UpdateProfileRequest;import com.collabspace.service.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users") @RequiredArgsConstructor public class UserController {private final CurrentUserService current;private final AuthService auth;private final UserService users;@GetMapping("/me") public UserResponse me(){return auth.toDto(current.get());}@PutMapping("/me") public UserResponse update(@Valid @RequestBody UpdateProfileRequest r){return users.update(r);}}